mapper.select:
select count(1) from tl_tssh.rcgl_cqwsb_data t
where djxh=#{djxh} and ckbgdh=#{ckbgdh}
      and t.qyqr_zt in ('1','2') and t.swsh_zt='1'

select substr(t.xsfdsjswjg_dm,2,4) as xzqh_dm
from gt4_yyzc_zr_sjtb.dzfp_kpyw_fpjcxxb t
where fphm=#{jhpzh}

SELECT T.JKM_LEVEL
  FROM TL_TSSH.JKGL_DATA_QYJKM_JGB T
 WHERE T.DJXH = #{djxh}

SELECT MIN(t.jzxh) AS jzxh, COUNT(1) AS jzxsl
  FROM tl_tssh.CKTS_WBSJ_HG_BGD204 t
 WHERE t.bgdhgbh=#{bgdhgbh}

SELECT DJXH, BGDHGBH, CPH, QYRQ, QYD, WLXXLY_DM, FXDJ_DM
  FROM TL_TSSH.CKLLFX_DATA_BGDWL
 WHERE DJXH=#{djxh}
   AND BGDHGBH IN

       #{bgdh}

mapper.update:
UPDATE TL_TSSH.CKLLFX_DATA_BGDWL SET WLXXLY_DM = #{wlxxlyDm}, CPH = #{cph},
QYRQ = TO_DATE(#{qyrq, jdbcType=VARCHAR}, 'YYYY-MM-DD'),
QYD = #{qyd}, CKFPH=#{ckfph},CKFPBZ=#{ckfpbz},CKMXBZ=#{ckmxbz}, SJGXSJ = SYSDATE WHERE DJXH=#{djxh} AND BGDHGBH=#{bgdhgbh}

mapper.select:
SELECT BGDHGBH, TO_CHAR(CKRQ_1, 'YYYY-MM-DD') AS CKRQ_1, MYLAJ
  FROM TL_TSSH.CKLLFX_DATA_BGDWL
 WHERE DJXH=#{djxh}
   AND WLXXLY_DM IS NULL
   AND MYLAJ > #{p1val}
   AND CKRQ_1 >= TO_DATE('2026-05-01', 'YYYY-MM-DD')

select 1
from tl_admin.yj_data_yjxx a
inner join tl_admin.yj_sbxx_hz b on b.id = a.sbid
where a.nsrdzdah = #{nsrdzdah}
  and a.yj_object = #{spdm}
  and a.zbcode = '12301'
  and b.lcslid != #{lcslid}
  and rownum = 1

select 1
from tl_admin.yj_data_yjxx a
         inner join tl_admin.yj_sbxx_hz b on b.id = a.sbid
where a.nsrdzdah = #{nsrdzdah}
  and a.yj_object = #{spdm}
